def count_punctuation(sentence):
    count = 0
    punctuation = ['.', ',', ';', ':', '!', '?']

    for char in sentence:
        if char in punctuation:
            count += 1

    return count

sentence = "Hello, how are you today?"
print(count_punctuation(sentence))
